from concurrent.futures import ThreadPoolExecutor

import pytest


def square(x: int) -> int:
    return x * x


def sum_squares(xs: list[int], *, workers: int = 4) -> int:
    """Sum of square(x) for every x in xs, computing the squares in a
    thread pool of `workers` threads.

    The result is identical for every worker count (integer addition is
    exact, so chunking and completion order cannot change it). An empty
    list gives 0. Raises ValueError if workers < 1.
    """
    if workers < 1:
        raise ValueError("workers must be >= 1")
    with ThreadPoolExecutor(max_workers=workers) as pool:
        return sum(pool.map(square, xs))


def test_basic() -> None:
    assert sum_squares([1, 2, 3]) == 14


def test_empty() -> None:
    assert sum_squares([]) == 0


def test_single() -> None:
    assert sum_squares([7]) == 49


def test_negatives_and_zero() -> None:
    assert sum_squares([-3, 0, 3]) == 18


def test_large_values_exact() -> None:
    big = 10**12
    assert sum_squares([big, big]) == 2 * big * big


def test_does_not_mutate_input() -> None:
    xs = [3, 1, 2]
    sum_squares(xs)
    assert xs == [3, 1, 2]


@pytest.mark.parametrize("workers", [1, 2, 3, 4, 8, 16, 100])
def test_same_result_at_every_worker_count(workers: int) -> None:
    xs = list(range(-50, 51))
    expected = sum(square(x) for x in xs)
    assert sum_squares(xs, workers=workers) == expected


@pytest.mark.parametrize("workers", [1, 2, 5, 64])
def test_fewer_items_than_workers(workers: int) -> None:
    assert sum_squares([2, 3], workers=workers) == 13
    assert sum_squares([], workers=workers) == 0


def test_matches_across_worker_counts_on_large_input() -> None:
    xs = [(i * 7919) % 1001 - 500 for i in range(5000)]
    expected = sum(x * x for x in xs)
    results = {sum_squares(xs, workers=w) for w in (1, 2, 3, 7, 16)}
    assert results == {expected}


def test_default_workers_matches_explicit() -> None:
    xs = [5, -4, 3]
    assert sum_squares(xs) == sum_squares(xs, workers=1) == 50


@pytest.mark.parametrize("workers", [0, -1])
def test_invalid_workers(workers: int) -> None:
    with pytest.raises(ValueError):
        sum_squares([1, 2], workers=workers)


def test_uses_thread_pool(monkeypatch: pytest.MonkeyPatch) -> None:
    created: list[int] = []

    class Spy(ThreadPoolExecutor):
        def __init__(self, max_workers: int | None = None, *a: object, **k: object) -> None:
            created.append(max_workers if max_workers is not None else -1)
            super().__init__(max_workers)

    import sys

    monkeypatch.setattr(sys.modules[__name__], "ThreadPoolExecutor", Spy)
    assert sum_squares([1, 2, 3], workers=3) == 14
    assert created and created[0] >= 1

